    final_amount numeric;
BEGIN
    IF amount <= 0 THEN
        RAISE EXCEPTION 'Invalid amount';
    ELSIF amount < 100 THEN
        discount_rate := 0.0;
    ELSIF amount < 500 THEN
        discount_rate := 0.05;
